const HEX2 = (n) => (n < 16 ? '0' : '') + n.toString(16).toUpperCase();

// 当日 12:00 的儒略日整数（与 lunar-javascript 同日柱基准）
const noonJD = (y, m, d) => Date.UTC(y, m - 1, d) / DAY_MS + 2440588;
function dayGZIndex(y, m, d) {
  const off = Math.floor(noonJD(y, m, d)) - 11;
  return { gan: ((off % 10) + 10) % 10, zhi: ((off % 12) + 12) % 12 };
}
// 立春为界的年干支（返回 {gan, zhi, gz, year}）
function yearGZByLiChun(y, m, d) {
  const s = Date.UTC(y, m - 1, d);
  const yy = s >= termSerial(y, 2) ? y : y - 1;
  const gan = ((yy - 4) % 10 + 10) % 10;
  const zhi = ((yy - 4) % 12 + 12) % 12;
  return { gan, zhi, gz: GAN[gan] + ZHI[zhi], year: yy };
}
// 月柱：index 0=寅月 .. 11=丑月（以「节」的日界划分）
function monthBlockIdx(y, m, d) {
  const s = Date.UTC(y, m - 1, d);
  const base = s >= termSerial(y, 2) ? y : y - 1;   // 立春周期所属公历年
  const starts = [];
  for (let k = 0; k <= 10; k++) starts.push(termSerial(base, 2 + 2 * k));  // 立春…大雪
  starts.push(termSerial(base + 1, 0));                                    // 次年小寒
  let idx = 0;
  for (let k = 0; k < 12; k++) if (s >= starts[k]) idx = k;
  return idx;
}
// 月干支（返回 {gan, zhi, gz}）
function monthGZ(y, m, d) {
  const idx = monthBlockIdx(y, m, d);
  const i6 = idx <= 8 ? idx : idx - 12;              // 转换到 6tail 坐标 -3..8
  const ganLC = yearGZByLiChun(y, m, d).gan;
  const offset = ((((ganLC + (i6 < 0 ? 1 : 0)) % 5) + 1) * 2) % 10;
  const ganIdx = ((i6 < 0 ? i6 + 10 : i6) + offset) % 10;
  const zhiIdx = ((i6 < 0 ? i6 + 12 : i6) + 2) % 12;
  return { gan: ganIdx, zhi: zhiIdx, gz: GAN[ganIdx] + ZHI[zhiIdx] };
}

/* ===================== 宜忌（与 lunar-javascript 同表同逻辑） ===================== */
function dayYiJi(dayGZ, monthGZ) {
  const day = HEX2(gzIndex(dayGZ));
  const month = HEX2(gzIndex(monthGZ));
  let right = DAY_YI_JI();
  let index = right.indexOf(day + '=');
  let yi = [], ji = [];
  while (index > -1) {
    right = right.substring(index + 3);
    let left = right;
    if (left.indexOf('=') > -1) left = left.substring(0, left.indexOf('=') - 2);
    const months = left.substring(0, left.indexOf(':'));
    let matched = false;
    for (let i = 0, j = months.length; i < j; i += 2) {
      if (months.substring(i, i + 2) === month) { matched = true; break; }
    }
    if (matched) {
      const ys = left.substring(left.indexOf(':') + 1);
      const yEnd = ys.substring(0, ys.indexOf(','));
      for (let i = 0; i < yEnd.length; i += 2) yi.push(D.YI_JI[parseInt(yEnd.substring(i, i + 2), 16)]);
      const js = left.substring(left.indexOf(',') + 1);
      for (let i = 0; i < js.length; i += 2) ji.push(D.YI_JI[parseInt(js.substring(i, i + 2), 16)]);
      break;
    }
    index = right.indexOf(day + '=');
  }
  const none = D.SHEN_SHA[0];
  const uniq = (a) => a.filter((v, i) => v && a.indexOf(v) === i);
  yi = uniq(yi); ji = uniq(ji);
  if (!yi.length) yi = [none];
  if (!ji.length) ji = [none];
  // 宜忌互斥去重：同一天里既宜又忌的条目，以「忌」为准（通书惯例）
  const jiSet = new Set(ji);
  yi = yi.filter((v) => !jiSet.has(v));
  if (!yi.length) yi = [none];
  return { yi, ji };
}

/* ===================== 当日黄历 ===================== */
function almanac(y, m, d) {
  const lunar = solarToLunar(y, m, d);
  const dg = dayGZIndex(y, m, d);
  const dayGZ = GAN[dg.gan] + ZHI[dg.zhi];
  // 月柱：宜忌按日界月柱（getMonthInGanZhi），干支展示同源
  const mgz = monthGZ(y, m, d);
  const ygz = yearGZByLiChun(y, m, d);
  // 农历年干支（春节为界）
  const lunarY = lunar.year;
  const lunarGan = ((lunarY - 4) % 10 + 10) % 10;
  const lunarZhi = ((lunarY - 4) % 12 + 12) % 12;
  const week = new Date(Date.UTC(y, m - 1, d)).getUTCDay();
  const zhiXing = D.ZHI_XING[((dg.zhi - mgz.zhi + 12) % 12) + 1];
  const tianShen = D.TIAN_SHEN[(dg.zhi + D.ZHI_TIAN_SHEN_OFFSET[ZHI[mgz.zhi]]) % 12 + 1];
  const xiu = D.XIU[ZHI[dg.zhi] + week] || '';
  const { yi, ji } = dayYiJi(dayGZ, mgz.gz);
  // 当日节气（若今天是交节日）
  let jieQiToday = '';
  for (let i = 0; i < 24; i++) {
    if (termSerial(y, i) === Date.UTC(y, m - 1, d)) { jieQiToday = TERM_NAMES[i]; break; }
  }
  return {
    y, m, d, week,
    lunar, lunarMonth: MONTH_CN[lunar.month - 1], lunarDay: DAY_CN[lunar.day - 1],
    lunarText: (lunar.isLeap ? '闰' : '') + MONTH_CN[lunar.month - 1] + '月' + DAY_CN[lunar.day - 1],
    lunarMonthFull: (lunar.isLeap ? '闰' : '') + MONTH_CN[lunar.month - 1],
    lunarYearGZ: GAN[lunarGan] + ZHI[lunarZhi],
    sx: SX[lunarZhi],
    yearGZ: ygz.gz,
    dayGZ, monthGZ: mgz.gz,
    dayGanIdx: dg.gan, dayZhiIdx: dg.zhi,
    zhiXing, tianShen,
    tianShenType: D.TIAN_SHEN_TYPE[tianShen] || '',
    xiu, xiuLuck: D.XIU_LUCK[xiu] || '', zheng: D.ZHENG[xiu] || '', animal: D.ANIMAL[xiu] || '',
    chong: (D.CHONG_GAN[dg.gan] || '') + D.CHONG[dg.zhi] + '·' + SX[ZHI.indexOf(D.CHONG[dg.zhi])],
    chongDesc: D.CHONG[dg.zhi],
    chongSX: SX[ZHI.indexOf(D.CHONG[dg.zhi])],
    chongGZ: (D.CHONG_GAN[dg.gan] || '') + D.CHONG[dg.zhi],
    sha: D.SHA[ZHI[dg.zhi]] || '',
    nayin: D.NAYIN[dayGZ] || '',
    wuXing: (D.WU_XING_GAN[GAN[dg.gan]] || '') + (D.WU_XING_ZHI[ZHI[dg.zhi]] || ''),
    pengZu: [D.PENGZU_GAN[dg.gan + 1] || '', D.PENGZU_ZHI[dg.zhi + 1] || ''],
    taiShen: D.POSITION_TAI_DAY[gzIndex(dayGZ)] || '',
    xi: D.POSITION_XI[dg.gan + 1] || '', fu: D.POSITION_FU_2[dg.gan + 1] || '',
    cai: D.POSITION_CAI[dg.gan + 1] || '', yangGui: D.POSITION_YANG_GUI[dg.gan + 1] || '',
    yinGui: D.POSITION_YIN_GUI[dg.gan + 1] || '',
    yi, ji, jieQiToday,
  };
}

