/* ---- 省份归一化（思路同 Hark 油价模板的 normalizeProvince）----
 * 源站按行政区划索引数据时，用户可写 福建 / 福建省 / 闽 / fujian，统一归一到标准省名 */
const PROVINCES = {
  北京: ['北京', '京', 'beijing'], 天津: ['天津', '津', 'tianjin'], 河北: ['河北', '冀', 'hebei'],
  山西: ['山西', '晋', 'shanxi'], 内蒙古: ['内蒙古', '蒙', 'neimenggu'], 辽宁: ['辽宁', '辽', 'liaoning'],
  吉林: ['吉林', '吉', 'jilin'], 黑龙江: ['黑龙江', '黑', 'heilongjiang'], 上海: ['上海', '沪', 'shanghai'],
  江苏: ['江苏', '苏', 'jiangsu'], 浙江: ['浙江', '浙', 'zhejiang'], 安徽: ['安徽', '皖', 'anhui'],
  福建: ['福建', '闽', 'fujian'], 江西: ['江西', '赣', 'jiangxi'], 山东: ['山东', '鲁', 'shandong'],
  河南: ['河南', '豫', 'henan'], 湖北: ['湖北', '鄂', 'hubei'], 湖南: ['湖南', '湘', 'hunan'],
  广东: ['广东', '粤', 'guangdong'], 广西: ['广西', '桂', 'guangxi'], 海南: ['海南', '琼', 'hainan'],
  重庆: ['重庆', '渝', 'chongqing'], 四川: ['四川', '川', 'sichuan'], 贵州: ['贵州', '黔', 'guizhou'],
  云南: ['云南', '滇', 'yunnan'], 西藏: ['西藏', '藏', 'xizang'], 陕西: ['陕西', '陕', 'shaanxi'],
  甘肃: ['甘肃', '甘', 'gansu'], 青海: ['青海', '青', 'qinghai'], 宁夏: ['宁夏', '宁', 'ningxia'],
  新疆: ['新疆', '新', 'xinjiang'], 台湾: ['台湾', '台', 'taiwan'], 香港: ['香港', '港', 'hongkong'],
  澳门: ['澳门', '澳', 'macau'],
};
function normalizeProvince(v) {
  const raw = String(v || '').trim();
  if (!raw) return '';
  const key = raw.replace(/[省市区]|自治区|特别行政区|壮族|回族|维吾尔|藏族|蒙古/g, '');
  for (const name of Object.keys(PROVINCES)) {
    const alias = PROVINCES[name];
    if (name === key || name === raw || alias.some((a) => a === key || a.toLowerCase() === raw.toLowerCase())) return name;
  }
  for (const name of Object.keys(PROVINCES)) {
    if (name.length > 1 && (raw.indexOf(name) >= 0 || name.indexOf(raw) >= 0)) return name;
  }
  return raw;
}

/* ---- 地名归一化：去行政后缀、拆分隔符、剥省份前后缀 ---- */
const PROV_NAMES = ['内蒙古', '黑龙江', '广西', '西藏', '宁夏', '新疆', '香港', '澳门', '北京', '天津', '上海', '重庆',
  '河北', '山西', '辽宁', '吉林', '江苏', '浙江', '安徽', '福建', '江西', '山东', '河南', '湖北', '湖南', '广东',
  '海南', '四川', '贵州', '云南', '陕西', '甘肃', '青海', '台湾'];
const stripSuffix = (s) => s.replace(/(市|县|区|省|自治区|特别行政区|自治州|地区|盟)$/g, '');

function candidates(raw) {
  const out = [];
  const push = (v) => { v = (v || '').trim(); if (v && out.indexOf(v) < 0) out.push(v); };
  const whole = raw.trim();
  push(whole);
  push(stripSuffix(whole));
  push(whole.replace(/^(中国|中华人民共和国)[·,，、\s]*/, ''));
  push(whole.replace(/(省|自治区|特别行政区)/g, ''));
  const noProv = whole.match(/^.{2,8}?(省|自治区|特别行政区)([\s\S]+)$/);
  if (noProv && noProv[2]) { push(noProv[2]); push(stripSuffix(noProv[2])); }
  // 按分隔符拆开，逐段尝试（"莆田,福建" / "福建 莆田" / "福建省莆田市"）
  for (const part of whole.split(/[,，、\/\s]+/)) { push(part); push(stripSuffix(part)); }
  // 无分隔符的「省份+城市」连写（"福建莆田" / "莆田福建"）
  for (const p of PROV_NAMES) {
    if (whole.length > p.length) {
      if (whole.indexOf(p) === 0) { push(whole.slice(p.length)); push(stripSuffix(whole.slice(p.length))); }
      if (whole.lastIndexOf(p) === whole.length - p.length) { push(whole.slice(0, whole.length - p.length)); }
    }
  }
  return out;
}

// 离线：从内置表解析
function lookupCity(raw) {
  for (const c of candidates(raw)) {
    const k = CITY[c] ? c : (CITY[stripSuffix(c)] ? stripSuffix(c) : null);
    if (k) return { lat: CITY[k][0], lon: CITY[k][1], name: k };
  }
  return null;
}

function coordOf(raw) {
  const m = raw.match(/^\s*(-?\d+(?:\.\d+)?)\s*[,，\s]\s*(-?\d+(?:\.\d+)?)\s*$/);
  if (!m) return null;
  const lat = Number(m[1]);
  const lon = Number(m[2]);
  if (!(lat >= -90 && lat <= 90 && lon >= -180 && lon <= 180)) return null;
  let name = null, bd = 0.25;                     // 约 25km 内反查城市名
  for (const k of Object.keys(CITY)) {
    const d = Math.max(Math.abs(CITY[k][0] - lat), Math.abs(CITY[k][1] - lon));
    if (d < bd) { bd = d; name = k; }
  }
  return { lat, lon, name: name || `${lat},${lon}` };
}

async function httpJSON(ctx, url, headers, timeout) {
  const r = await ctx.http.get(url, { headers: headers || {}, timeout: timeout || 12000 });
  if (typeof r === 'string') return JSON.parse(r);
  if (r.json) return await r.json();
  return JSON.parse(await r.text());
}

// 在线兜底：OSM Nominatim（中文解析准确，长缓存）
async function geocodeOSM(ctx, raw, province) {
  let list = candidates(raw);
  if (province) {
    // 带省份限定优先（区县级地名重名多，如「顺义」全国不止一处）
    const withProv = list.slice(0, 2).map((q) => q + ' ' + province);
    list = withProv.concat(list.filter((q) => withProv.indexOf(q) < 0));
  }
  for (const q of list) {
    const key = 'geo_' + q;
    let hit = null;
    try { hit = ctx.storage.getJSON(key); } catch (_) {}
    if (hit && hit.lat) return hit;
    try {
      const url = 'https://nominatim.openstreetmap.org/search?q=' + encodeURIComponent(q) +
        '&countrycodes=cn&format=json&limit=6&accept-language=zh';
      const rs = await httpJSON(ctx, url, { 'User-Agent': 'EgernAlmanacWidget/1.0' }, 12000);
      const rank = (r) => (({ boundary: 0, place: 1 })[r.class] ?? 9) * 10 +
        (({ city: 0, municipality: 1, administrative: 2, town: 3, province: 4, state: 5, region: 6 })[r.addresstype] ?? 9);
      const ok = (rs || []).filter((r) => r.class === 'boundary' || r.class === 'place');
      const p = (ok.length ? ok : rs || []).sort((a, b) => rank(a) - rank(b) || (b.importance || 0) - (a.importance || 0))[0];
      if (p) {
        hit = { lat: Number(p.lat), lon: Number(p.lon), name: q };
        try { ctx.storage.setJSON(key, hit); } catch (_) {}
        return hit;
      }
    } catch (_) { /* 换下一个候选 */ }
  }
  return null;
}

// IP 定位（Egern 走代理时会得到节点所在地，仅作兜底）
async function geoIP(ctx) {
  const key = 'geo_ip';
  try { const c = ctx.storage.getJSON(key); if (c && c.lat && Date.now() - (c.ts || 0) < 86400000) return c; } catch (_) {}
  const sources = [
    { url: 'http://ip-api.com/json/?lang=zh-CN', get: (j) => (j.status === 'success' ? { lat: j.lat, lon: j.lon, name: j.city } : null) },
    { url: 'https://ipapi.co/json/', get: (j) => (j.latitude ? { lat: j.latitude, lon: j.longitude, name: j.city } : null) },
  ];
  for (const s of sources) {
    try {
      const j = await httpJSON(ctx, s.url, {}, 8000);
      const p = s.get(j);
      if (p && p.lat) { p.ts = Date.now(); try { ctx.storage.setJSON(key, p); } catch (_) {} return p; }
    } catch (_) {}
  }
  return null;
}

// 统一入口：把 LOCATION 解析成 {lat, lon, name}
async function resolvePlace(ctx, loc) {
  const raw = String(loc || '').trim();
  const cacheKey = 'place_' + (raw || 'auto');
  try { const c = ctx.storage.getJSON(cacheKey); if (c && c.lat) return c; } catch (_) {}

  let place = null;
  if (raw) {
    // 归一化到「城市名 + 省份」，同时给出坐标（坐标源用）
    const parts = raw.split(/[,，\s]+/).filter(Boolean);
    const nameOnly = parts.find((x) => !coordOf(x)) || raw;
    const provRaw = parts.find((x) => x !== nameOnly && PROVINCES[normalizeProvince(x)]) || '';
    const province = normalizeProvince(provRaw);
    const cityName = stripSuffix(nameOnly.replace(/(省|自治区|特别行政区)/g, '').replace(/^.*?(?:省|自治区)/, '')) || nameOnly;
    // 只用「城市片段」查表：整串里的省份片段（"顺义,北京" 的 北京）不该抢占匹配
    place = coordOf(raw) || lookupCity(nameOnly) || (await geocodeOSM(ctx, nameOnly, province));
    if (!place) {
      // 坐标解析不出来也照样能用：nmc / apihz 按中文地名索引，与油价模板同理
      place = { lat: null, lon: null, name: cityName, province, fallbackName: true };
    } else {
      place.province = place.province || province;
      if (cityName && cityName.length < (place.name || '').length) place.name = cityName;
    }
  } else {
    place = await geoIP(ctx);
  }
  if (!place) place = { lat: 39.9075, lon: 116.397, name: '北京' };
  try { ctx.storage.setJSON(cacheKey, place); } catch (_) {}
  return place;
}

/* ---------------- 天气描述 → 统一图标 ---------------- */
const DESC_ICON = [
  [/龙卷|台风|飓风/, 'tornado'],
  [/雷阵雨伴有冰雹|雷阵雨伴冰雹|雷暴/, 'cloud.bolt.rain.fill'],
  [/雷阵雨|雷/, 'cloud.bolt.rain.fill'],
  [/暴雨|大暴雨|特大暴雨|大雨/, 'cloud.heavyrain.fill'],
  [/雨夹雪|冻雨|雨雪/, 'cloud.sleet.fill'],
  [/中雨|小雨|阵雨|雨|降水/, 'cloud.rain.fill'],
  [/毛毛雨|细雨/, 'cloud.drizzle.fill'],
  [/暴雪|大雪|中雪|小雪|阵雪|雪/, 'cloud.snow.fill'],
  [/雾|霾|浮尘|扬沙|沙尘|尘/, 'cloud.fog.fill'],
  [/阴/, 'cloud.fill'],
  [/多云|少云|晴间多云/, 'cloud.sun.fill'],
  [/晴/, 'sun.max.fill'],
];
const NIGHT_FIX = { 'sun.max.fill': 'moon.stars.fill', 'cloud.sun.fill': 'cloud.moon.fill' };

function descIcon(desc, isDay) {
  const d = String(desc || '').trim();
  for (const [re, ic] of DESC_ICON) {
    if (re.test(d)) return [!isDay && NIGHT_FIX[ic] ? NIGHT_FIX[ic] : ic, d];
  }
  return ['cloud.fill', d || '—'];
}

/* ---------------- 各源适配器：统一输出 ---------------- */
const outcome = (o) => Object.assign({
  ts: Date.now(), src: '', place: '', lat: 0, lon: 0, unit: 'c',
  temp: null, feel: null, hum: null, wind: null, windDir: '', pressure: null, precip: null,
  isDay: 1, desc: '', icon: 'cloud.fill', sunrise: '', sunset: '',
  hourly: [], days: [],
}, o);

const isDayNow = (sunrise, sunset) => {
  const hm = (s) => { const m = String(s || '').match(/(\d{1,2}):(\d{2})/); return m ? Number(m[1]) * 60 + Number(m[2]) : null; };
  const a = hm(sunrise), b = hm(sunset);
  if (a === null || b === null) return 1;
  const d = new Date(Date.now() + 8 * 3600000);
  const cur = d.getUTCHours() * 60 + d.getUTCMinutes();
  return cur >= a && cur < b ? 1 : 0;
};

/* ---- 1) Open-Meteo ---- */
const WMO_CN = [[0, '晴'], [1, '晴间多云'], [2, '多云'], [3, '阴'], [45, '雾'], [48, '雾凇'], [51, '毛毛雨'], [53, '毛毛雨'], [55, '毛毛雨'],
  [56, '冻雨'], [57, '冻雨'], [61, '小雨'], [63, '中雨'], [65, '大雨'], [66, '冻雨'], [67, '冻雨'], [71, '小雪'], [73, '中雪'], [75, '大雪'],
  [77, '米雪'], [80, '阵雨'], [81, '阵雨'], [82, '强阵雨'], [85, '阵雪'], [86, '阵雪'], [95, '雷阵雨'], [96, '雷阵雨伴冰雹'], [99, '雷暴']];
const wmoText = (c) => { let t = '—'; for (const [k, v] of WMO_CN) if (c >= k) t = v; return t; };

async function srcOpenMeteo(ctx, place, unit) {
  const tz = 'Asia/Shanghai';
  const url = 'https://api.open-meteo.com/v1/forecast?latitude=' + place.lat + '&longitude=' + place.lon +
    '&current=temperature_2m,relative_humidity_2m,apparent_temperature,is_day,precipitation,weather_code,wind_speed_10m,wind_direction_10m,surface_pressure' +
    '&hourly=temperature_2m,weather_code,precipitation_probability' +
    '&daily=weather_code,temperature_2m_max,temperature_2m_min,sunrise,sunset,precipitation_probability_max,uv_index_max' +
    '&timezone=' + encodeURIComponent(tz) + '&forecast_days=4&temperature_unit=' + (unit === 'f' ? 'fahrenheit' : 'celsius');
  const j = await httpJSON(ctx, url, {}, 15000);
  const c = j.current || {};
  const d = j.daily || {};
  const h = j.hourly || {};
  const now = new Date(Date.now() + 8 * 3600000);
  const nowIso = now.toISOString().slice(0, 13) + ':00';
  let start = (h.time || []).findIndex((t) => t >= nowIso);
  if (start < 0) start = 0;
  const hourly = [];
  for (let i = start; i < Math.min(start + 8, (h.time || []).length); i++) {
    hourly.push({
      t: (h.time[i] || '').slice(11, 16), temp: Math.round(h.temperature_2m[i]), pop: h.precipitation_probability ? h.precipitation_probability[i] : null,
      desc: wmoText(h.weather_code[i]),
    });
  }
  const days = [];
  for (let i = 0; i < Math.min(4, (d.time || []).length); i++) {
    days.push({
      date: d.time[i], max: Math.round(d.temperature_2m_max[i]), min: Math.round(d.temperature_2m_min[i]),
      desc: wmoText(d.weather_code[i]), pop: d.precipitation_probability_max ? d.precipitation_probability_max[i] : null,
      uv: d.uv_index_max ? d.uv_index_max[i] : null,
      sunrise: (d.sunrise[i] || '').slice(11, 16), sunset: (d.sunset[i] || '').slice(11, 16),
    });
  }
  const t0 = days[0] || {};
  const isDay = c.is_day !== undefined ? Number(c.is_day) : isDayNow(t0.sunrise, t0.sunset);
  const [icon, desc] = descIcon(wmoText(c.weather_code), isDay);
  return outcome({
    src: 'open-meteo', place: place.name, lat: place.lat, lon: place.lon, unit,
    temp: Math.round(c.temperature_2m), feel: Math.round(c.apparent_temperature), hum: Math.round(c.relative_humidity_2m),
    wind: Math.round(c.wind_speed_10m), windDir: dirName(c.wind_direction_10m), pressure: Math.round(c.surface_pressure),
    precip: c.precipitation, isDay, desc, icon,
    sunrise: t0.sunrise || '', sunset: t0.sunset || '', hourly, days,
  });
}
const DIRS = ['北', '东北', '东', '东南', '南', '西南', '西', '西北'];
const dirName = (deg) => (deg === undefined || deg === null ? '' : DIRS[Math.round(Number(deg) / 45) % 8] + '风');

/* ---- 2) 中央气象台 nmc.cn（官方，国内直连） ---- */
async function nmcCode(ctx, name) {
  const key = 'nmc_' + name;
  try { const c = ctx.storage.getJSON(key); if (c && c.code) return c.code; } catch (_) {}
  const j = await httpJSON(ctx, 'http://www.nmc.cn/rest/position?keyword=' + encodeURIComponent(name),
    { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)', 'Referer': 'http://www.nmc.cn/' }, 12000);
  const list = Array.isArray(j) ? j : [j];
  const hit = list.find((x) => x && x.code);
  if (!hit) return null;
  try { ctx.storage.setJSON(key, { code: hit.code, ts: Date.now() }); } catch (_) {}
  return hit.code;
}

async function srcNMC(ctx, place, unit) {
  const name = String(place.name || '').replace(/(市|县|区|省)$/g, '');
  const code = await nmcCode(ctx, name);
  if (!code) throw new Error('nmc 未找到该城市: ' + name);
  const j = await httpJSON(ctx, 'http://www.nmc.cn/rest/weather?stationid=' + code,
    { 'User-Agent': 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)', 'Referer': 'http://www.nmc.cn/' }, 12000);
  const data = j && j.data;
  if (!data || !data.real || !data.real.weather) throw new Error('nmc 返回异常');
  const r = data.real;
  const detail = (data.predict && data.predict.detail) || [];
  const conv = (v) => (unit === 'f' ? Math.round((Number(v) * 9) / 5 + 32) : Math.round(Number(v)));
  const days = detail.slice(0, 4).map((d) => ({
    date: String(d.date || '').slice(0, 10), max: conv(d.day && d.day.weather && d.day.weather.temperature),
    min: conv(d.night && d.night.weather && d.night.weather.temperature),
    desc: (d.day && d.day.weather && d.day.weather.info) || '—', pop: null, uv: null,
    sunrise: '', sunset: '',
  }));
  const sunrise = ((r.sunriseSunset || {}).sunrise || '').slice(11, 16);
  const sunset = ((r.sunriseSunset || {}).sunset || '').slice(11, 16);
  const isDay = isDayNow(sunrise, sunset);
  const [icon, desc] = descIcon(r.weather.info, isDay);
  return outcome({
    src: 'nmc', place: place.name, lat: place.lat, lon: place.lon, unit,
    temp: conv(r.weather.temperature), feel: r.weather.feelst ? conv(r.weather.feelst) : null,
    hum: Math.round(r.weather.humidity), wind: Math.round((r.wind || {}).speed || 0), windDir: (r.wind || {}).direct || '',
    pressure: r.weather.airpressure && r.weather.airpressure < 9000 ? Math.round(r.weather.airpressure) : null,
    precip: r.weather.rain, isDay, desc, icon, sunrise, sunset, hourly: [], days,
  });
}

/* ---- 3) apihz（国内聚合，免 key） ---- */
async function srcApihz(ctx, place, unit) {
  const full = String(place.name || '');
  let sheng = normalizeProvince(place.province || '');
  if (['北京', '天津', '上海', '重庆'].indexOf(full) >= 0) sheng = full;   // 直辖市
  const city = full;
  const url = 'https://cn.apihz.cn/api/tianqi/tqyb.php?id=88888888&key=88888888' +
    (sheng ? '&sheng=' + encodeURIComponent(sheng) : '') + '&place=' + encodeURIComponent(city);
  const j = await httpJSON(ctx, url, {}, 12000);
  if (!j || j.code !== 200) throw new Error('apihz 无数据');
  const conv = (v) => (unit === 'f' ? Math.round((Number(v) * 9) / 5 + 32) : Math.round(Number(v)));
  const n = j.nowinfo || {};
  const isDay = isDayNow('06:00', '18:00');
  const [icon, desc] = descIcon(j.weather1, isDay);
  const days = [];
  const today = new Date(Date.now() + 8 * 3600000);
  if (j.weather1) days.push({ date: today.toISOString().slice(0, 10), max: conv(j.wd1), min: conv(j.wd2), desc: j.weather1, pop: null, uv: null, sunrise: '', sunset: '' });
  if (j.weather2) {
    const t2 = new Date(today.getTime() + 86400000);
    days.push({ date: t2.toISOString().slice(0, 10), max: conv(j.wd1), min: conv(j.wd2), desc: j.weather2, pop: null, uv: null, sunrise: '', sunset: '' });
  }
  return outcome({
    src: 'apihz', place: place.name, lat: Number(j.lat) || place.lat, lon: Number(j.lon) || place.lon, unit,
    temp: conv(n.temperature), feel: n.feelst ? conv(n.feelst) : null, hum: Math.round(n.humidity),
    wind: n.windSpeed !== undefined ? Math.round(Number(n.windSpeed) * 3.6) : null, windDir: n.windDirection || '',
    pressure: n.pressure, precip: n.precipitation, isDay, desc, icon, hourly: [], days,
  });
}

/* ---- 4) wttr.in ---- */
async function srcWttr(ctx, place, unit) {
  const url = 'https://wttr.in/' + encodeURIComponent(place.lat + ',' + place.lon) + '?format=j1&lang=zh';
  const j = await httpJSON(ctx, url, { 'User-Agent': 'curl/8' }, 15000);
  const c = (j.current_condition || [])[0] || {};
  const conv = (v) => (unit === 'f' ? Math.round((Number(v) * 9) / 5 + 32) : Math.round(Number(v)));
  const days = (j.weather || []).slice(0, 4).map((d) => ({
    date: d.date, max: conv(d.maxtempC), min: conv(d.mintempC),
    desc: ((d.hourly || [])[4] || {}).lang_zh ? ((d.hourly || [])[4].lang_zh[0] || {}).value : (d.hourly || [])[4] && (d.hourly || [])[4].weatherDesc ? (d.hourly || [])[4].weatherDesc[0].value : '—',
    pop: null, uv: d.uvIndex, sunrise: ((d.astronomy || [])[0] || {}).sunrise, sunset: ((d.astronomy || [])[0] || {}).sunset,
  }));
  const zh = c.lang_zh && c.lang_zh[0] ? c.lang_zh[0].value : (c.weatherDesc ? c.weatherDesc[0].value : '—');
  const isDay = isDayNow(((j.weather || [])[0] || {}).astronomy ? j.weather[0].astronomy[0].sunrise : '06:00', '18:00');
  const [icon, desc] = descIcon(zh, isDay);
  return outcome({
    src: 'wttr', place: place.name, lat: place.lat, lon: place.lon, unit,
    temp: conv(c.temp_C), feel: conv(c.FeelsLikeC), hum: Number(c.humidity),
    wind: Number(c.windspeedKmph), windDir: c.winddir16Point || '', pressure: Number(c.pressure), precip: Number(c.precipMM),
    isDay, desc, icon, hourly: [], days,
  });
}

/* ---- 5) 彩云（需自填 token） ---- */
async function srcCaiyun(ctx, place, unit, env) {
  const token = String((env && (env.CAIYUN_TOKEN || env.CAIYUN_KEY)) || '').trim();
  if (!token) throw new Error('未配置 CAIYUN_TOKEN');
  const url = 'https://api.caiyunapp.com/v2.6/' + token + '/' + place.lon + ',' + place.lat +
    '/weather?alert=true&dailysteps=4&hourlysteps=8';
  const j = await httpJSON(ctx, url, {}, 12000);
  if (j.status !== 'ok') throw new Error('彩云: ' + (j.error || 'error'));
  const r = j.result || {};
  const rt = r.realtime || {};
  const dv = r.daily || {};
  const isDay = rt.life_index && rt.life_index.ultraviolet ? 1 : 1;
  const skycon = r.realtime && r.realtime.skycon ? skyconText(r.realtime.skycon) : '—';
  const [icon, desc] = descIcon(skycon, isDay);
  const days = ((dv.skycon || []).slice(0, 4)).map((s, i) => ({
    date: String(s.date || '').slice(0, 10),
    max: dv.temperature_2m_max && dv.temperature_2m_max[i] ? Math.round(dv.temperature_2m_max[i].value) : null,
    min: dv.temperature_2m_min && dv.temperature_2m_min[i] ? Math.round(dv.temperature_2m_min[i].value) : null,
    desc: skyconText(s.value), pop: null, uv: null, sunrise: '', sunset: '',
  }));
  return outcome({
    src: 'caiyun', place: place.name, lat: place.lat, lon: place.lon, unit,
    temp: Math.round(rt.temperature), feel: rt.apparent_temperature !== undefined ? Math.round(rt.apparent_temperature) : null,
    hum: rt.humidity !== undefined ? Math.round(rt.humidity * 100) : null,
    wind: rt.wind ? Math.round(rt.wind.speed * 3.6) : null, windDir: rt.wind && rt.wind.direction !== undefined ? dirName(rt.wind.direction + 180) : '',
    pressure: rt.pressure !== undefined ? Math.round(rt.pressure / 100) : null, precip: null,
    isDay, desc, icon, hourly: [], days,
  });
}
const SKYCON = { CLEAR_DAY: '晴', CLEAR_NIGHT: '晴', PARTLY_CLOUDY_DAY: '多云', PARTLY_CLOUDY_NIGHT: '多云', CLOUDY: '阴', LIGHT_HAZE: '轻度雾霾', MODERATE_HAZE: '中度雾霾', HEAVY_HAZE: '重度雾霾', LIGHT_RAIN: '小雨', MODERATE_RAIN: '中雨', HEAVY_RAIN: '大雨', STORM_RAIN: '暴雨', FOG: '雾', LIGHT_SNOW: '小雪', MODERATE_SNOW: '中雪', HEAVY_SNOW: '大雪', STORM_SNOW: '暴雪', DUST: '浮尘', SAND: '沙尘', WIND: '大风' };
const skyconText = (v) => SKYCON[String(v || '').toUpperCase()] || '—';

const SOURCES = { 'open-meteo': srcOpenMeteo, 'nmc': srcNMC, 'apihz': srcApihz, 'wttr': srcWttr, 'caiyun': srcCaiyun };
const AUTO_ORDER = ['open-meteo', 'nmc', 'apihz', 'wttr'];

// 取天气：按 SOURCE 选择；auto / 失败时自动降级
async function fetchWeather(ctx, place, unit, source, env) {
  const want = String(source || 'auto').trim().toLowerCase();
  const order = want === 'auto' || !SOURCES[want] ? AUTO_ORDER : [want].concat(AUTO_ORDER.filter((s) => s !== want));
  let lastErr = null;
  for (const name of order) {
    const needCoord = name === 'open-meteo' || name === 'wttr';
    const hasCoord = place.lat !== null && place.lat !== undefined && !isNaN(place.lat);
    const hasName = /[^\d.,\s-]/.test(String(place.name || ''));
    if (needCoord && !hasCoord) continue;                        // 坐标源没坐标 → 跳过
    if (!needCoord && !hasName) continue;                        // 地名源没名字 → 跳过
    try {
      const w = await SOURCES[name](ctx, place, unit, env);
      if (w && w.temp !== null && w.temp !== undefined && !isNaN(w.temp)) return w;
    } catch (e) { lastErr = e; }
  }
  throw lastErr || new Error('全部天气源不可用');
}

/* ===================== 渲染层：方案 D（卡片骨架 + 宜忌色块） ===================== */
/* 配色：亮/暗由系统主题自动切换（{light,dark} 对象） */
const C = {
  bg: { light: '#F2F6F3', dark: '#0F1714' },
  bg2: { light: '#E8F0EA', dark: '#0A120F' },
  bg3: { light: '#DCE8E0', dark: '#060B09' },
  ink: { light: '#182420', dark: '#E9F2EC' },
  sub: { light: '#5E7268', dark: '#83988C' },
  faint: { light: '#8FA398', dark: '#5A6D62' },
  zhu: { light: '#B5382C', dark: '#FF6B5E' },
  gold: { light: '#9A7420', dark: '#DDB055' },
  card: { light: '#FFFFFFB8', dark: '#FFFFFF0F' },
  yi: { light: '#1E7A4C', dark: '#3FBF7F' },
  yiBg: { light: '#DDF0E2', dark: '#12301C' },
  jiBg: { light: '#FAE3DF', dark: '#331510' },
};
const WD = ['日', '一', '二', '三', '四', '五', '六'];
const JOIN = (a, n) => (a || []).slice(0, n).join(' ');

/* 节点构造 */
const T = (text, opt) => {
  const o = Object.assign({}, opt || {});
  const f = {};
  if (o.size !== undefined) { f.size = o.size; delete o.size; }
  if (o.weight !== undefined) { f.weight = o.weight; delete o.weight; }
  if (Object.keys(f).length) o.font = f;
  if (o.lineLimit !== undefined) { o.maxLines = o.lineLimit; delete o.lineLimit; }
  return Object.assign({ type: 'text', text: String(text) }, o);
};
const IMG = (name, size, color) => ({ type: 'image', src: 'sf-symbol:' + name, width: size, height: size, color });
const STACK = (dir, opt, kids) => Object.assign({ type: 'stack', direction: dir, children: kids || [] }, opt);
const COL = (opt, kids) => STACK('column', Object.assign({ alignItems: 'start' }, opt || {}), kids);
const ROW = (opt, kids) => STACK('row', Object.assign({ alignItems: 'center' }, opt || {}), kids);
const SP = (flex) => ({ type: 'spacer', flex: flex === undefined ? 1 : flex });
const CARD = (opt, kids) => COL(Object.assign({ padding: 10, borderRadius: 13, backgroundColor: C.card }, opt), kids);
// 行内容器：靠父 column 的 alignItems:"center" 实现水平居中（官方语义：column + center = 子元素水平居中）
const CENTER = (kids, opt) => ROW(Object.assign({ gap: 6 }, opt || {}), kids);
// 根节点必须是 widget（官方：垂直布局、对齐固定左上角、唯一支持 refreshAfter 的元素）
const WIDGET_ONLY = ['children', 'gap', 'padding', 'backgroundColor', 'backgroundGradient', 'backgroundImage',
  'refreshAfter', 'url', 'flex', 'borderRadius', 'shadowColor', 'shadowRadius', 'shadowOffset'];
const root = (opt, kids) => {
  const o = Object.assign({}, opt || {});
  for (const k of Object.keys(o)) if (WIDGET_ONLY.indexOf(k) < 0) delete o[k];   // 剔除 stack 专属属性
  return Object.assign({ type: 'widget', children: kids || [] }, o);
};
const bgGradient = () => ({
  type: 'linear', colors: [C.bg, C.bg2, C.bg3], stops: [0, 0.55, 1],
  startPoint: { x: 0, y: 0 }, endPoint: { x: 1, y: 1 },
});
const WTEMP = (t) => (t === null || t === undefined ? C.sub
  : t <= 0 ? { light: '#2B6CB0', dark: '#6BB6FF' }
    : t <= 10 ? { light: '#1F7A8C', dark: '#5AC8D8' }
      : t <= 20 ? { light: '#1E7A4C', dark: '#4ED8A0' }
        : t <= 28 ? { light: '#B06000', dark: '#FFA94D' }
          : { light: '#B5382C', dark: '#FF6B5E' });

/* 宜 / 忌 色块 —— 黄历核心信息，做成视觉主角 */
function yiJiBlock(A, n, gap) {
  const line = (ch, words, tagCol, bgCol) => STACK('row', {
    padding: [3.5, 10], borderRadius: 9, backgroundColor: bgCol, gap: 7, alignItems: 'center',
  }, [
    T(ch, { size: 13, weight: 'bold', textColor: tagCol, lineLimit: 1 }),
    T(n === null ? (words || []).join(' ') : JOIN(words, n), { size: 12, textColor: C.ink, lineLimit: 1, minScale: 0.62 }),
  ]);
  return COL({ gap: gap === undefined ? 6 : gap }, [line('宜', A.yi, C.yi, C.yiBg), line('忌', A.ji, C.zhu, C.jiBg)]);
}
const titleChip = (o) => (o && o.title ? [T(o.title, { size: 10, textColor: C.faint, lineLimit: 1, minScale: 0.7 })] : []);
const solarLine = (A, size) => T(`${A.dayGZ}日 · ${A.zhiXing}日 · 周${WD[A.week]}`, { size: size || 10.5, textColor: C.sub, lineLimit: 1, minScale: 0.72 });
const metaLine = (A, size) => T(`冲${A.chongSX}(${A.chongGZ}) 煞${A.sha} ${A.tianShen}·${A.tianShenType}`, { size: size || 9.5, textColor: C.faint, lineLimit: 1, minScale: 0.7 });
function tmrLine(A, size) {
  const n = new Date(Date.UTC(A.y, A.m - 1, A.d) + 86400000);
  const B = almanac(n.getUTCFullYear(), n.getUTCMonth() + 1, n.getUTCDate());
  return T(`明日 ${B.lunarText} ${B.dayGZ}日 · 宜${JOIN(B.yi, 2)} 忌${JOIN(B.ji, 2)}`,
    { size: size || 11, textColor: C.gold, lineLimit: 1, minScale: 0.62 });
}
const wxIcon = (W) => (W && W.icon ? W.icon : 'cloud.fill');
const dayLabel = (iso, i) => (i === 0 ? '明天' : i === 1 ? '后天' : ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][new Date(iso + 'T12:00:00Z').getUTCDay()]);
function nowW(W, size) {
  return ROW({ gap: 5, alignItems: 'center' }, [
    IMG(wxIcon(W), size, C.gold),
    T(`${W.temp}°`, { size: Math.round(size * 1.75), weight: 'bold', textColor: WTEMP(W.temp), lineLimit: 1, minScale: 0.7 }),
  ]);
}
/* ===================== 各尺寸布局 ===================== */
function buildSmall(A, W, env, o) {
  const kids = [];
  if (o.wantA) {
    kids.push(CENTER([
      T(A.lunarText, { size: 21, weight: 'bold', textColor: C.ink, lineLimit: 1, minScale: 0.8 }),
      T(`${A.yearGZ}年(${A.sx})`, { size: 10, weight: 'bold', textColor: C.gold, lineLimit: 1, minScale: 0.75 }),
    ]));
    kids.push(CENTER([solarLine(A, 10.5)]));
    kids.push(SP(0.15));
    kids.push(CENTER([yiJiBlock(A, o.yiN, 5)]));
    kids.push(SP(0.15));
  }
  if (o.wantW && W) {
    kids.push(CENTER([ROW({ gap: 5, alignItems: 'center' }, [
      IMG(wxIcon(W), 17, C.gold),
      T(`${W.temp}°`, { size: 19, weight: 'bold', textColor: WTEMP(W.temp), lineLimit: 1, minScale: 0.75 }),
      T(W.desc, { size: 11, textColor: C.sub, lineLimit: 1, minScale: 0.7 }),
    ])]));
  } else if (o.wantW) {
    kids.push(CENTER([T('天气待更新', { size: 11, textColor: C.faint })]));
  }
  return root({ padding: 12, gap: 5, backgroundGradient: o.plain ? undefined : bgGradient() }, [COL({ gap: 5, flex: 1, alignItems: 'center' }, kids)]);
}


function buildMedium(A, W, env, o) {
  const left = o.wantA ? COL({ gap: 3, flex: 2.2, alignItems: 'center' }, [
    CENTER([
      T(A.lunarText, { size: 20.5, weight: 'bold', textColor: C.ink, lineLimit: 1, minScale: 0.8 }),
      T(`${A.yearGZ}年(${A.sx})`, { size: 10.5, weight: 'bold', textColor: C.gold, lineLimit: 1, minScale: 0.72 }),
    ]),
    CENTER([solarLine(A)]),
    SP(0.08),
    CENTER([yiJiBlock(A, o.yiN, 4)]),
    SP(0.08),
    CENTER([metaLine(A, 9)]),
  ]) : COL({ gap: 4, flex: 2.2 }, []);
  const right = (o.wantW && W) ? COL({ flex: 1, gap: 2, alignItems: 'center', padding: [10, 6], borderRadius: 16, backgroundColor: C.card }, [
    SP(0.2),
    IMG(wxIcon(W), 22, C.gold),
    T(`${W.temp}°`, { size: 27, weight: 'semibold', textColor: WTEMP(W.temp), lineLimit: 1, minScale: 0.65, textAlign: 'center' }),
    T(W.desc, { size: 11, textColor: C.sub, lineLimit: 1, minScale: 0.72 }),
    T(`↑${W.days[0] ? W.days[0].max : '--'}° ↓${W.days[0] ? W.days[0].min : '--'}°`, { size: 11, textColor: C.ink, lineLimit: 1, minScale: 0.75 }),
    T(`湿${W.hum}% 风${W.wind}`, { size: 10, textColor: C.faint, lineLimit: 1, minScale: 0.7 }),
    SP(0.2),
  ]) : COL({ flex: 1 }, []);
  let strip = null;
  if (o.wantW && W && (W.hourly || []).length >= 4) {
    const cells = W.hourly.slice(0, 4).map((h) => ROW({ gap: 3, flex: 1, alignItems: 'center' }, [
      T(h.t, { size: 9, textColor: C.faint, lineLimit: 1, minScale: 0.6 }),
      IMG(h && h.icon ? h.icon : 'cloud.fill', 9, C.gold),
      T(`${h.temp}°`, { size: 10, weight: 'semibold', textColor: WTEMP(h.temp), lineLimit: 1, minScale: 0.6 }),
    ]));
    strip = ROW({ gap: 2, alignItems: 'center' }, cells);
  }
  const kids = [ROW({ gap: 9, flex: 1, alignItems: 'center' }, [left, right])];
  if (strip) kids.push(strip);
  return root({ padding: [10, 13], gap: 5, backgroundGradient: o.plain ? undefined : bgGradient() }, kids);
}

function buildLarge(A, W, env, o) {
  const cards = [];
  if (o.wantW && W) {
    const all = W.hourly || [];
    const hours = all.slice(0, all.length > 6 ? 8 : 6);
    cards.push(CARD({ gap: 6 }, [
      ROW({ gap: 8, alignItems: 'center' }, [
        IMG(wxIcon(W), 22, C.gold),
        T(`${W.temp}°`, { size: 34, weight: 'bold', textColor: WTEMP(W.temp), lineLimit: 1, minScale: 0.7 }),
        SP(),
        COL({ gap: 1, flex: 1, alignItems: 'end' }, [
          T(`↑${W.days[0] ? W.days[0].max : '--'}° ↓${W.days[0] ? W.days[0].min : '--'}°`, { size: 12, textColor: C.ink, lineLimit: 1, minScale: 0.8 }),
          T(`体感${W.feel}°`, { size: 10, textColor: C.faint, lineLimit: 1, minScale: 0.8 }),
        ]),
      ]),
      T(`${W.place} · ${W.desc} · 湿${W.hum}% 风${W.wind}km/h`, { size: 10, textColor: C.sub, lineLimit: 1, minScale: 0.68 }),
      hours.length ? ROW({ gap: 4, flex: 0.7 }, hours.map((h) => COL({ gap: 2, flex: 1, alignItems: 'center' }, [
        T(h.t, { size: 10, textColor: C.faint, lineLimit: 1, minScale: 0.7 }),
        IMG(h && h.icon ? h.icon : 'cloud.fill', 11, C.gold),
        T(`${h.temp}°`, { size: 11, weight: 'semibold', textColor: WTEMP(h.temp), lineLimit: 1, minScale: 0.7 }),
      ]))) : SP(0),
      ROW({ gap: 6 }, W.days.slice(1, 4).map((d, i) => ROW({ gap: 6, flex: 1, alignItems: 'center' }, [
        T(dayLabel(d.date, i), { size: 10, textColor: C.sub, lineLimit: 1, minScale: 0.7 }),
        T(`${d.max}°/${d.min}°`, { size: 12, weight: 'semibold', textColor: C.ink, lineLimit: 1, minScale: 0.7 }),
      ]))),
    ]));

  }
  if (o.wantA) {
    cards.push(CARD({ gap: 4, flex: 1, alignItems: 'center' }, [
      ROW({ gap: 6, alignItems: 'center' }, [
        T(A.lunarText, { size: 23, weight: 'bold', textColor: C.ink, lineLimit: 1, minScale: 0.8 }),
        T(`${A.yearGZ}年(${A.sx})`, { size: 11, weight: 'bold', textColor: C.gold, lineLimit: 1, minScale: 0.75 }),
        SP(),
        ...titleChip(o),
      ]),
      T(`${A.dayGZ}日 · ${A.zhiXing}日 · 周${WD[A.week]} · ${A.xiu}宿(${A.xiuLuck}) ${A.nayin}`, { size: 10.5, textColor: C.sub, lineLimit: 1, minScale: 0.62 }),
      SP(0.12),
      yiJiBlock(A, o.yiN, 6),
      SP(0.12),
      metaLine(A, 10),
      T(`喜${A.xi} 财${A.cai} 福${A.fu} · 胎神${A.taiShen} · ${A.pengZu[0].slice(0, 4)} ${A.pengZu[1].slice(0, 4)}`, { size: 10, textColor: C.faint, lineLimit: 1, minScale: 0.58 }),
      SP(0.12),
      tmrLine(A, 11),
    ]));
  }
  if (!cards.length) cards.push(CARD({ flex: 1 }, [T('无数据', { size: 12, textColor: C.sub })]));
  return root({ padding: 13, gap: 8, backgroundGradient: o.plain ? undefined : bgGradient() }, cards);
}

/* ===================== 锁屏（accessory） ===================== */
function buildLockRect(A, W) {
  return root({ padding: 3, gap: 1 }, [COL({ gap: 1, flex: 1 }, [
    T(`${A.lunarText} 宜${JOIN(A.yi, 1)} 忌${JOIN(A.ji, 1)}`, { size: 11, textColor: '#FFFFFF', lineLimit: 1, minScale: 0.6 }),
    T(`${A.zhiXing}日 冲${A.chongSX}${W ? ' · ' + W.temp + '° ' + W.desc : ''}`, { size: 9, textColor: '#FFFFFFCC', lineLimit: 1, minScale: 0.6 }),
  ])]);
}
function buildLockCirc(A, W) {
  return root({ padding: 2, gap: 0 }, [COL({ gap: 0, flex: 1, alignItems: 'center' }, [
    W ? IMG(wxIcon(W), 18, '#FFFFFF') : T('历', { size: 14, weight: 'bold', textColor: '#FFFFFF' }),
    W ? T(`${W.temp}°`, { size: 14, weight: 'bold', textColor: '#FFFFFF', lineLimit: 1, minScale: 0.6 })
      : T(A.lunarText, { size: 11, textColor: '#FFFFFF', lineLimit: 1, minScale: 0.6 }),
  ])]);
}
function buildLockInline(A, W) {
  return root({ padding: 0, gap: 0 }, [COL({ gap: 0, flex: 1 }, [
    T(`${A.lunarText} 宜${JOIN(A.yi, 1)} 忌${JOIN(A.ji, 1)}${W ? ' ' + W.temp + '°' : ''}`, { size: 12, textColor: '#FFFFFF', lineLimit: 1, minScale: 0.6 }),
  ])]);
}


/* ===================== 入口 ===================== */
// 参数读取：多别名 + 中文名（与 Hark 油价模板 getEnv 同款）
const getEnv = (env, names, fallback = '') => {
  for (const name of names) {
    const v = env ? env[name] : undefined;
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return fallback;
};
const truthy = (v, dflt) => (v === '' || v === undefined || v === null ? dflt : !/^(0|false|no|off|否|关)$/i.test(String(v)));

export default async function (ctx) {
  const env = (ctx && ctx.env) || {};
  const fam = (ctx && ctx.widgetFamily) || 'systemMedium';

  // —— 地址：LOCATION 单参数，或 CITY(+PROVINCE) 分开填，或直接写经纬度 ——
  const city = getEnv(env, ['CITY', 'LOCATION', '城市', '地区', 'AREA']);
  const prov = getEnv(env, ['PROVINCE', '省份', '省', 'STATE']);
  const locRaw = (city && prov && city.indexOf(',') < 0) ? city + ',' + prov : (city || prov || 'auto');

  const source = getEnv(env, ['SOURCE', '天气源'], 'auto');
  const unit = /^(f|fahrenheit|华氏)$/i.test(getEnv(env, ['TEMP_UNIT', 'UNIT', '温度单位'], 'c')) ? 'f' : 'c';
  const wantW = truthy(getEnv(env, ['SHOW_WEATHER', '显示天气'], '1'), true);
  const wantA = truthy(getEnv(env, ['SHOW_ALMANAC', '显示黄历'], '1'), true);
  const plain = !truthy(getEnv(env, ['PLAINBG', '纯色底'], '0'), false);
  const ttlMin = Math.max(10, Math.min(180, parseInt(getEnv(env, ['REFRESH', 'REFRESH_MINUTES', '刷新间隔'], '30'), 10) || 30));
  const title = getEnv(env, ['TITLE', '标题']);

  const now = new Date(Date.now() + 8 * 3600000);        // 北京时间（UTC+8）
  const A = almanac(now.getUTCFullYear(), now.getUTCMonth() + 1, now.getUTCDate());
  const cap = { systemSmall: 3, systemMedium: 5, systemLarge: 6 }[fam] || 4;   // 每尺寸能放下的宜忌条数上限
  const yiN = Math.min(parseInt(getEnv(env, ['YI_COUNT', '宜忌条数'], String(cap)), 10) || cap, cap);
  const o = { yiN, wantA, wantW, title, plain };

  let W = null;
  if (wantW) {
    const ttl = ttlMin * 60000;
    const wxKey = 'wx_' + (locRaw || 'auto').replace(/[^0-9A-Za-z\u4e00-\u9fa5]/g, '') + '_' + unit + '_' + source;  // 按地点+单位+源隔离
    try { W = ctx.storage.getJSON(wxKey); } catch (_) {}
    if (!W || (Date.now() - (W.ts || 0)) > ttl || !W.lat) {
      try {
        const place = await resolvePlace(ctx, locRaw === 'auto' ? '' : locRaw);
        W = await fetchWeather(ctx, place, unit, source, env);
        try { ctx.storage.setJSON(wxKey, W); } catch (_) {}
      } catch (_) { /* 请求失败：保留旧缓存 */ }
    }
  }

  const base = { url: getEnv(env, ['URL', '跳转链接'], 'https://www.weather.com.cn/') };
  if (plain) base.backgroundColor = C.bg2;
  // 刷新时机：取「天气刷新间隔」与「北京时间次日 00:05」的较早者（跨天必须换黄历）
  const nextMid = Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1) + 5 * 60000 - 8 * 3600000;
  base.refreshAfter = new Date(Math.min(Date.now() + ttlMin * 60000, nextMid)).toISOString();
  const mk = (n) => Object.assign(n, base);

  if (fam.startsWith('accessory')) {
    if (fam === 'accessoryInline') return mk(buildLockInline(A, W));
    if (fam === 'accessoryCircular') return mk(buildLockCirc(A, W));
    return mk(buildLockRect(A, W));
  }
  if (fam === 'systemSmall') return mk(buildSmall(A, W, env, o));
  if (fam === 'systemLarge' || fam === 'systemExtraLarge') return mk(buildLarge(A, W, env, o));
  return mk(buildMedium(A, W, env, o));
}
